// message_catalog.rs is generated by build.rs from the `ctr!` calls of `src/`
// and the `.po` files of the GUI's `i18n/`.
include!(concat!(env!("OUT_DIR"), "/message_catalog.rs"));

/// [`ctr!`](sc_slicer_gui_base::ctr), which looks its messages up in this
/// crate's catalog above.
pub(crate) use sc_slicer_gui_base::ctr;

#[cfg(test)]
mod tests {
    use std::rc::Rc;

    use slint::platform::software_renderer::{MinimalSoftwareWindow, RepaintBufferType};
    use slint::platform::{Platform, WindowAdapter, set_platform};
    use slint::{PlatformError, SelectBundledTranslationError};

    use super::LANGUAGES;

    /// A Slint platform that opens no OS window.
    struct HeadlessPlatform;

    impl Platform for HeadlessPlatform {
        fn create_window_adapter(&self) -> Result<Rc<dyn WindowAdapter>, PlatformError> {
            Ok(MinimalSoftwareWindow::new(RepaintBufferType::ReusedBuffer))
        }
    }

    /// This crate's catalog is written apart from the GUI crate's, so check on
    /// its own that its languages are Slint's, in Slint's order: otherwise a
    /// message of this crate would show in another language.
    #[test]
    fn the_catalog_has_the_languages_of_slints_bundle_in_their_order() {
        let bundled = std::thread::spawn(|| {
            set_platform(Box::new(HeadlessPlatform)).expect("a new thread has no platform yet");
            let dialog = sc_slicer_gui_ui::AboutWindow::new().expect("a headless component");
            let languages = match slint::select_bundled_translation("not-a-language") {
                Err(SelectBundledTranslationError::LanguageNotFound {
                    available_languages,
                }) => available_languages
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>(),
                other => panic!("expected an unknown language, got {other:?}"),
            };
            drop(dialog);
            languages
        })
        .join()
        .expect("the thread ends");
        assert_eq!(bundled, LANGUAGES);
    }
}
